package com.univmar.order.domain;
import com.univmar.quotation.domain.Quotation; import com.univmar.shared.domain.BaseEntity; import com.univmar.user.domain.User; import jakarta.persistence.*; import java.math.BigDecimal;
@Entity @Table(name="customer_orders") public class Order extends BaseEntity { @OneToOne(optional=false) @JoinColumn(name="quotation_id",unique=true) private Quotation quotation; @ManyToOne(optional=false) @JoinColumn(name="customer_id") private User customer; @Column(nullable=false,unique=true) private String orderNumber; @Enumerated(EnumType.STRING) @Column(nullable=false) private OrderStatus status=OrderStatus.CONFIRMED; @Column(nullable=false,precision=19,scale=2) private BigDecimal totalSnapshot; protected Order(){} public Order(Quotation quote,String number){quotation=quote;customer=quote.getRequest().getCustomer();orderNumber=number;totalSnapshot=quote.getTotal();} public OrderStatus getStatus(){return status;} public String getOrderNumber(){return orderNumber;} public User getCustomer(){return customer;} public Quotation getQuotation(){return quotation;} public BigDecimal getTotalSnapshot(){return totalSnapshot;} public void transition(OrderStatus next){boolean legal=(status==OrderStatus.CONFIRMED&&(next==OrderStatus.PREPARING||next==OrderStatus.CANCELLED))||(status==OrderStatus.PREPARING&&(next==OrderStatus.READY||next==OrderStatus.CANCELLED))||(status==OrderStatus.READY&&next==OrderStatus.DELIVERED);if(!legal)throw new IllegalStateException("Illegal order status transition");status=next;} }
